 107→export interface SkillBackingBundle {
 108→  redis: Redis | null;
 109→  pinRepo: PinRepoLike | null;
 110→  /**
 111→   * BindingRepo 直接从 SessionStore 拿(injection pipeline 装配时已注入),
 112→   * 不重新构造,保证 bridge L2 反查用的实例和 handler 写 binding 的实例一致
 113→   * —— 单元测试注入 SessionStore.setBindingRepo 后,bridge 也读同一个 mock。
 114→   */
 115→  bindingRepo: BindingRepo | null;
