 220→interface SessionIdFields {
 221→  user_id: string;
 222→  team_id: string;
 223→  agent_id: string;
 224→  /**
 225→   * URL 路径侧的 agentSource（`claude-code` / `codebuddy` ...）—— 用于
 226→   * Repo 三段隔离键。从 SessionStore 里存储 session 的 keyId 反解出来
 227→   * （keyId 形如 `${agentSource}:${sessionId}`）。
 228→   */
 229→  agent_source: string;
 230→  /**
 231→   * Kernel tenant/instance ID for `x-tdai-service-id`. Extracted from
 232→   * `SessionInfo.space_id` (which itself was captured from the original
 233→   * request path `/{agent}/{spaceId}/...`). Undefined for legacy sessions
 234→   * created before space_id tracking — caller falls back to
 235→   * `config.coreSkill.serviceId`.
 236→   */
 237→  space_id?: string;
 238→  /**
 239→   * User API key (`x-tdai-user-key`). Captured during session init from the
 240→   * upstream request's api key exchange. Required by kernel /v3/meta/* endpoints
 241→   * to enforce per-user ACL/visibility. Missing here means the session upstream
 242→   * bypassed apikey verification — that's a programming bug, not a rejectable
 243→   * runtime state; team-wide search returns 500 rather than silently opening up.
 244→   */
 245→  user_key?: string;
 246→  /**
 247→   * Composite key actually used to load state from SessionStore
 248→   * (`${agentSource}:${sessionId}`). 用于埋点侧对齐 session_init_logs 的
 249→   * session_key —— 埋点不能猜前缀，必须用真实命中的 key。
 250→   */
 251→  composite_key?: string;
 252→}
 253→
 254→/**
 255→ * Bridge 只吃 2 个 header:
 256→ *   - x-conversation-id (或 x-session-id / x-chat-id / x-thread-id) → sessionId
 257→ *   - x-tdai-service-id → spaceId
 258→ *
 259→ * 不再依赖 Authorization 反查 userId —— 见 docs/design/2026-08-03-binding-flatten.md,
 260→ * L2 fallthrough 走拍平的 (spaceId, sessionId) → binding.json 直接 stamp。
 261→ */
 262→function deriveSessionId(c: Context): string | null {
 263→  return (
 264→    c.req.header("x-conversation-id") ??
 265→    c.req.header("x-session-id") ??
 266→    c.req.header("x-chat-id") ??
 267→    c.req.header("x-thread-id") ??
 268→    null
 269→  );
 270→}
 271→
 272→function stateToIdFields(
 273→  state: import("../session/types.js").SessionInitState | undefined,
 274→  matchedKey: string,
 275→): SessionIdFields | null {
 276→  if (!state || state.status !== "initialized" || !state.sessionInfo) return null;
 277→  const s = state.sessionInfo;
 278→  if (!s.user_id || !s.team_id || !s.agent_id) return null;
 279→  // agentSource 从 matchedKey 反解(命中的 L1 key 形如 `${agentSource}:${sessionId}`);
 280→  // L2b 分支直接从 binding.agentSource 拿(见 bindingToIdFields)。
 281→  const colonIdx = matchedKey.indexOf(":");
 282→  const agentSource = colonIdx > 0 ? matchedKey.slice(0, colonIdx) : "claude-code";
 283→  return {
 284→    user_id: s.user_id,
 285→    team_id: s.team_id,
 286→    agent_id: s.agent_id,
 287→    agent_source: agentSource,
 288→    space_id: s.space_id,
 289→    user_key: s.user_key,
 290→    composite_key: matchedKey,
 291→  };
 292→}
 293→
 294→function bindingToIdFields(
 295→  binding: import("../db/binding-repo.js").SessionBinding,
 296→  spaceId: string,
 297→  sessionId: string,
 298→): SessionIdFields | null {
 299→  if (binding.outcome !== "initialized") return null;
 300→  if (!binding.userId || !binding.teamId || !binding.agentId) return null;
 301→  const agentSource = binding.agentSource || "claude-code";
 302→  return {
 303→    user_id: binding.userId,
 304→    team_id: binding.teamId,
 305→    agent_id: binding.agentId,
 306→    agent_source: agentSource,
 307→    space_id: spaceId,
 308→    user_key: binding.userKey,
 309→    composite_key: `${agentSource}:${sessionId}`,
 310→  };
 311→}
