 336→/**
 337→ * L2 fallthrough —— 拍平后只吃 (spaceId, sessionId)。见
 338→ * docs/design/2026-08-03-binding-flatten.md。
 339→ *
 340→ * 不再走 verifyUserKey + getOrRecover 那条 4 段路径。原因:
 341→ *   1) bridge curl 模板没塞 Authorization: Bearer,verify 拿不到 userId
 342→ *   2) 拍平后 binding.json 里已经存了 user_id/team_id/agent_id/agent_source/user_key,
 343→ *      一次 GET 就够,不需要再补 kernel getAgent/getTask
 344→ */
 345→async function loadSessionIdsL2(
 346→  bindingRepo: BindingRepo | null,
 347→  spaceId: string,
 348→  sessionId: string,
 349→): Promise<SessionIdFields | null> {
 350→  if (!bindingRepo) return null;
 351→  try {
 352→    const binding = await bindingRepo.getBinding(spaceId, sessionId);
 353→    if (!binding) return null;
 354→    return bindingToIdFields(binding, spaceId, sessionId);
 355→  } catch (err) {
 356→    console.warn(`${TAG} L2 getBinding error space=${spaceId} sid=${sessionId}: ${(err as Error).message}`);
 357→    return null;
 358→  }
 359→}
 360→
 361→function envelope(code: number, message: string, httpStatus = 200) {
 362→  return new Response(
 363→    JSON.stringify({ code, message, request_id: `bridge-${Date.now()}` }),
 364→    { status: httpStatus, headers: { "content-type": "application/json" } },
 365→  );
 366→}
 367→
 368→function extractSubpath(path: string): string | null {
 369→  // path comes in as `/skill-bridge/v3/skill/<sub...>` (or the segment after
 370→  // the bridge prefix, depending on how it was mounted).
 371→  const m = path.match(/^\/skill-bridge\/v3\/skill\/(.+)$/);
 372→  if (!m) return null;
 373→  return m[1].replace(/\/+$/, "");
 374→}
