  48→ * 一个 5 参签名，spaceId 段直接吞掉即可（Redis 版 key 里不带 spaceId）。
  49→ *
  50→ * 之前 4 参签名 + 直接把 KvVersionPinRepo 塞给 PinRepoLike 会导致：
  51→ *   spaceId ← ids.user_id
  52→ *   userId  ← ids.agent_source
  53→ *   agentSource ← sessionKey
  54→ *   sessionId ← skillId
  55→ * → key 完全错乱且丢租户隔离；节点 B 读永远 miss，症状匹配
  56→ *   "写到 COS 但另一节点看不到"。见 docs/design/2026-07-13-proxy-multinode-state-audit.md P0-1.
  57→ */
  58→interface PinRepoLike {
  59→  getVersion(
  60→    spaceId: string,
  61→    userId: string,
  62→    agentSource: string,
  63→    sessionId: string,
  64→    skillId: string,
  65→  ): Promise<number | null>;
  66→  pinMany(
  67→    spaceId: string,
  68→    userId: string,
  69→    agentSource: string,
  70→    sessionId: string,
  71→    pairs: Array<{ skillId: string; version: number }>,
  72→  ): Promise<void>;
  73→  upsertVersion(
  74→    spaceId: string,
  75→    userId: string,
  76→    agentSource: string,
  77→    sessionId: string,
  78→    skillId: string,
  79→    version: number,
  80→  ): Promise<void>;
  81→}
  82→
  83→/**
  84→ * 把 4 参 Redis-based VersionPinRepo 包成 5 参 PinRepoLike。
  85→ * Redis key schema (skill:vpin:<userId>:<agentSource>:<sessionId>) 里本来
  86→ * 就不带 spaceId —— 单实例 Redis 一般跟 kernel-sts space 是一对一或不重叠，
  87→ * 沿用旧行为，spaceId 参数直接丢弃。
  88→ */
  89→function adaptRedisPinRepo(inner: VersionPinRepo): PinRepoLike {
  90→  return {
  91→    getVersion: (_space, u, a, s, sk) => inner.getVersion(u, a, s, sk),
  92→    pinMany:    (_space, u, a, s, pairs) => inner.pinMany(u, a, s, pairs),
  93→    upsertVersion: (_space, u, a, s, sk, v) => inner.upsertVersion(u, a, s, sk, v),
  94→  };
  95→}
  96→
  97→/**
  98→ * 装配决策 —— 单一入口，让 skill-bridge 拿到"当前生效的"存储组合。
  99→ *
 100→ *   storage.enabled + mode!=off → 走 ProxyStorage (KvVersionPinRepo)
 101→ *   否则如果 redis.enabled       → 走 Redis (VersionPinRepo)
 102→ *   否则                          → null (in-memory 兜底)
 103→ *
 104→ * 曾经这里还装配 KvExtractStore / RedisExtractStore 给老链路
 105→ * SkillExtractTrigger 用, 已随老链路一起删除。
 106→ */
 107→export interface SkillBackingBundle {
 108→  redis: Redis | null;
 109→  pinRepo: PinRepoLike | null;
 110→  /**
 111→   * BindingRepo 直接从 SessionStore 拿(injection pipeline 装配时已注入),
 112→   * 不重新构造,保证 bridge L2 反查用的实例和 handler 写 binding 的实例一致
 113→   * —— 单元测试注入 SessionStore.setBindingRepo 后,bridge 也读同一个 mock。
 114→   */
 115→  bindingRepo: BindingRepo | null;
 116→}
 117→
 118→function resolveBacking(config: ProxyConfig): SkillBackingBundle {
 119→  const bindingRepo = getSessionStore().getBindingRepo() ?? null;
 120→  if (config.storage?.enabled) {
 121→    const storage = getProxyStorage(config.storage);
 122→    return {
 123→      redis: null,
 124→      pinRepo: new KvVersionPinRepo(storage),
 125→      bindingRepo: bindingRepo ?? new KvBindingRepo(storage),
 126→    };
 127→  }
 128→  const redis = config.redis?.enabled ? getRedisClient(config.redis) : null;
 129→  return {
 130→    redis,
 131→    pinRepo: redis ? adaptRedisPinRepo(new VersionPinRepo(redis, config.redis?.ttlSeconds)) : null,
 132→    bindingRepo: bindingRepo ?? (redis ? new RedisBindingRepo(redis) : null),
 133→  };
 134→}
