 160→/**
 161→ * Write subpaths — rejected when `allowLlmWrite=false`.
 162→ *
 163→ * `extract` is here on purpose. It does not edit a skill, but it makes the
 164→ * extractor create one from the current conversation, and a skill created that
 165→ * way lands in the team pool exactly like one written through `create`. A
 166→ * read-only session that can still mint skills is not read-only; the 2026-09-06
 167→ * instruction audit found the gate covering the six editing subpaths and
 168→ * leaving this one open.
 169→ */
 170→const WRITE_SUBPATHS = new Set<string>([
 171→  "create",
 172→  "update",
 173→  "patch",
 174→  "delete",
 175→  "files/write",
 176→  "files/remove",
 177→  "extract",
 178→]);
