 189→/**
 190→ * Version pinning — see docs/design/2026-06-29-skill-version-pinning.md.
 191→ *
 192→ * Read ops: proxy injects `version` into outbound so plugin returns the pinned
 193→ *   version's content (instead of head). Cross-tool consistency.
 194→ * Write ops: proxy injects `expected_version` for optimistic locking. If head
 195→ *   moved (external update), plugin returns 40901 SKILL_VERSION_STALE.
 196→ * Delete / create / extract / search / listing / list / versions / files-download
 197→ *   do NOT participate (soft-delete doesn't bump version; others are stateless).
 198→ */
 199→const READ_VERSION_OPS = new Set<string>(["get", "files/read"]);
 200→
 201→/**
 202→ * Read ops that must honour the same visibility whitelist as `search`.
 203→ *
 204→ * Before this, the three read paths disagreed about scope: `search` was
 205→ * team-visible (whitelist A ∪ B), `get-by-name` was owner-only (core looks up
 206→ * by (team, caller agent, name)), and `get` / `files/read` were team-wide with
 207→ * no visibility check at all (core scopes by team only). Two consequences,
 208→ * both seen in a real run: a consumer could *find* another agent's team-shared
 209→ * skill via search and then get 40401 reading it by name; and the same
 210→ * consumer could read any skill in the team by id — private ones included.
 211→ */
 212→const READ_VISIBILITY_OPS = new Set<string>(["get", "get-by-name", "files/read"]);
 213→const WRITE_LOCK_OPS = new Set<string>([
 214→  "update",
 215→  "patch",
 216→  "files/write",
 217→  "files/remove",
 218→]);
