 376→/**
 377→ * Contract for the ACL/visibility resolver invoked by team-wide search.
 378→ * Production implementation calls MetadataClient.listAccessibleAssets with
 379→ * asset_type='skill' + action='read' + visibility='team'. Tests inject a stub.
 380→ *
 381→ * No caching: skill_search is low-frequency (0-3 times per session), meta call
 382→ * is ~tens-of-ms next to a seconds-long LLM turn, and a cache would introduce
 383→ * a stale window that contradicts the panel (a visibility flip on the panel
 384→ * should be visible to the LLM's next search immediately).
 385→ */
 386→export type VisibleSkillIdsResolver = (input: {
 387→  user_id: string;
 388→  team_id: string;
 389→  user_key: string;
 390→  space_id?: string;
 391→}) => Promise<{
 392→  ids: string[];
 393→  /**
 394→   * The same assets with their names, when the resolver has them. Optional so
 395→   * a resolver that returns ids alone (older callers, tests) keeps working;
 396→   * without it get-by-name can resolve only the caller's own skills.
 397→   */
 398→  assets?: Array<{ asset_id: string; name?: string; owner_user_id?: string }>;
 399→}>;
 400→
 401→export interface SkillBridgeDeps {
 402→  /** Override fetcher (tests). */
 403→  fetcher?: typeof fetch;
 404→  /** Override `Date.now` (tests). */
 405→  now?: () => number;
 406→  /**
 407→   * Override the visibility whitelist lookup (tests). When omitted, the bridge
 408→   * uses the production resolver that calls kernel /v3/meta/asset/list-accessible.
 409→   */
 410→  resolveVisibleSkillIds?: VisibleSkillIdsResolver;
 411→  /**
 412→   * Override the core skill client (tests). When omitted, uses the singleton
 413→   * built from config. Used by team-search to enumerate agent-owned skills
 414→   * (B) and already-injected skills (C) — see whitelist composition below.
 415→   */
 416→  coreClient?: CoreSkillClient;
 417→}
 418→
 419→/** A team skill as `listSkills` reports it, reduced to what visibility needs. */
 420→export interface TeamSkillRef {
 421→  skill_id: string;
 422→  name: string;
 423→  owner_agent_id?: string;
 424→}
 425→
 426→export type ReadVisibilityDecision =
 427→  | { kind: "forward" }
 428→  | { kind: "rewrite"; skillId: string }
 429→  | { kind: "reject"; reason: string; message: string };
 430→
 431→/**
 432→ * Decide how a read op proceeds, given the visibility whitelist.
 433→ *
 434→ * Pure: no I/O, no session — so it can be tested directly, which matters
 435→ * because this is an authorization decision and the handler around it needs a
 436→ * live session to exercise.
 437→ *
 438→ *   get / files/read   the id must be in the whitelist, else reject. This is
 439→ *                      what closes the bypass: core scopes these by team only.
 440→ *   get-by-name        resolve the name among *visible* team skills and rewrite
 441→ *                      to `get` by id — that is what lets a consumer read a
 442→ *                      skill it found through search. Prefer the caller's own
 443→ *                      skill on a name clash; with no own skill and more than
 444→ *                      one visible match, do not guess: forward unchanged and
 445→ *                      let core answer as it always has.
 446→ *   anything else      forward unchanged.
 447→ *
 448→ * A name that resolves to nothing visible is also forwarded unchanged rather
 449→ * than rejected: core's owner-scoped lookup will 40401 exactly as before, and
 450→ * a private skill of another agent stays invisible — its existence is not
 451→ * revealed by a different error code. Likewise a rejected `get` says only
 452→ * "not visible", whether the id is private or does not exist.
 453→ */
 454→export function decideReadVisibility(input: {
 455→  sub: string;
 456→  inboundBody: Record<string, unknown>;
 457→  whitelist: Set<string>;
 458→  teamSkills: TeamSkillRef[];
 459→  callerAgentId: string;
 460→}): ReadVisibilityDecision {
 461→  const { sub, inboundBody, whitelist, teamSkills, callerAgentId } = input;
 462→
 463→  if (sub === "get" || sub === "files/read") {
 464→    const skillId = typeof inboundBody.skill_id === "string" ? inboundBody.skill_id : "";
 465→    if (!skillId) return { kind: "forward" }; // schema validation upstream will reject
 466→    if (whitelist.has(skillId)) return { kind: "forward" };
 467→    return {
 468→      kind: "reject",
 469→      reason: "not_visible",
 470→      message: `skill ${skillId} is not visible to agent ${callerAgentId}`,
 471→    };
 472→  }
 473→
 474→  if (sub === "get-by-name") {
 475→    const name = typeof inboundBody.skill_name === "string" ? inboundBody.skill_name : "";
 476→    if (!name) return { kind: "forward" };
 477→    const visible = teamSkills.filter((t) => t.name === name && whitelist.has(t.skill_id));
 478→    if (visible.length === 0) return { kind: "forward" };
 479→    const own = visible.find((t) => t.owner_agent_id === callerAgentId);
 480→    if (own) return { kind: "rewrite", skillId: own.skill_id };
 481→    if (visible.length === 1) return { kind: "rewrite", skillId: visible[0].skill_id };
 482→    return { kind: "forward" };
 483→  }
 484→
 485→  return { kind: "forward" };
 486→}
 487→
 488→/**
 489→ * The read whitelist for read ops, with names attached so `get-by-name` can
 490→ * resolve across it.
 491→ *
 492→ *   A = meta list-accessible(purpose='use')   every asset this user may read
 493→ *       on the model's path: admitted (approved) ones only, the caller's own
 494→ *       included — and it carries each asset's name, which is where names
 495→ *       for other agents' skills come from
 496→ *   B = coreClient.listSkills(team, caller agent)   the caller's own skills,
 497→ *       used for names and agent ids only
 498→ *
 499→ * Until 2026-09-08 the whitelist was A(visibility='team') ∪ B, and B let the
 500→ * caller's own candidates and rejected skills back in: admission is a
 501→ * property of the asset, not of who is asking, so B no longer widens the
 502→ * whitelist. Core applies the same rule on its side (skill-handlers
 503→ * admissionFilter); this list is the proxy's own copy of it, so a stale
 504→ * proxy fails closed rather than open.
 505→ *
 506→ * There is deliberately no team-wide `listSkills` here. An earlier version
 507→ * called it with team_id alone, and CoreSkillClient.normalizeTeamAgent fills
 508→ * an empty agent_id with "default" — so the call listed the skills owned by an
 509→ * agent named "default": none, and no error. Name resolution then found
 510→ * nothing, get-by-name was forwarded unchanged, and the consumer got 40401
 511→ * exactly as before the fix, with the fix silently doing nothing.
 512→ *
 513→ * Failure policy mirrors search: A failing is fail-closed (an empty whitelist,
 514→ * never an unfiltered read); B failing degrades to A only.
 515→ */
 516→export async function computeReadWhitelist(input: {
 517→  ids: { user_id: string; team_id: string; agent_id: string; user_key?: string; space_id?: string };
 518→  resolver: VisibleSkillIdsResolver;
 519→  coreClient: Pick<CoreSkillClient, "listSkills">;
 520→}): Promise<{ ok: true; whitelist: Set<string>; teamSkills: TeamSkillRef[]; namesFromA: boolean } | { ok: false; err: Error }> {
 521→  const { ids, resolver, coreClient } = input;
 522→
 523→  const promiseA = resolver({
 524→    user_id: ids.user_id, team_id: ids.team_id, user_key: ids.user_key ?? "", space_id: ids.space_id,
 525→  }).then((r) => ({ ok: true as const, ids: r.ids, assets: r.assets ?? [] }))
 526→    .catch((err) => ({ ok: false as const, err: err as Error }));
 527→
 528→  const promiseB = coreClient.listSkills(
 529→    { team_id: ids.team_id, agent_id: ids.agent_id, pagination: { limit: 1000 } },
 530→    { serviceId: ids.space_id },
 531→  ).then((r) => r.items.map((s) => ({ skill_id: s.skill_id, name: s.name, owner_agent_id: s.owner_agent_id ?? ids.agent_id })))
 532→    .catch((err) => {
 533→      console.warn(`${TAG} read whitelist own-skills list (B) failed, treating as empty: ${(err as Error).message}`);
 534→      return [] as TeamSkillRef[];
 535→    });
 536→
 537→  const [aResult, own] = await Promise.all([promiseA, promiseB]);
 538→  if (!aResult.ok) return { ok: false, err: aResult.err };
 539→
 540→  const whitelist = new Set<string>(aResult.ids);
 541→  // Own skills contribute names and agent ids, never ids the whitelist lacks.
 542→  const ownAdmitted = own.filter((s) => whitelist.has(s.skill_id));
 543→  const ownIds = new Set(ownAdmitted.map((s) => s.skill_id));
 544→  // A's entries that are not the caller's own carry no agent id from meta, so
 545→  // they are recorded as "someone else's" — which is all the clash rule needs.
 546→  const fromA: TeamSkillRef[] = aResult.assets
 547→    .filter((a) => a.name && !ownIds.has(a.asset_id))
 548→    .map((a) => ({ skill_id: a.asset_id, name: a.name as string, owner_agent_id: undefined }));
 549→
 550→  return {
 551→    ok: true,
 552→    whitelist,
 553→    teamSkills: [...ownAdmitted, ...fromA],
 554→    namesFromA: aResult.assets.length > 0,
 555→  };
 556→}
 557→
 558→/**
 559→ * Plugin's hard upper bound for /v3/skill/search `top_k` (see
 560→ * searchRequestSchema in plugin — z.number().int().min(1).max(50)).
 561→ *
 562→ * We overfetch to this cap on team-wide search so the response-side visibility
 563→ * filter has room to drop non-whitelisted items without starving the LLM. The
 564→ * BM25 top-50 is a strict superset of top-N (for N ≤ 50), so slicing after the
 565→ * filter yields the same ordering as if plugin had returned exactly N.
 566→ *
 567→ * Cost: ~20KB of extra JSON per team search + a Set.has per item. Trivial.
 568→ * Failure mode: only if the team has more than 50 team-visible skills that
 569→ * match the query AND enough of the top-50 hits are non-whitelisted to leave
 570→ * fewer than N — vanishingly unlikely for the current corpus size. If it ever
 571→ * matters, raise plugin's cap; this stays as-is.
 572→ *
 573→ * TODO(upgrade): 长期来看，如果观察到 team search 过滤后剩余条数常 < 用户
 574→ * top_k（whitelist merged 显著大于 50，或 filter 命中率 P95 < 0.2），说明
 575→ * 该 team 的 skill 池已把 top-50 撑爆，overfetch 兜不住 → 升级为请求侧
 576→ * 过滤（proxy 传 `skill_ids: [...]` → core 在 pool 内精确检索）。
 577→ * 见 `docs/design/2026-08-10-skill-search-scope-fix.md` §3 Plan A。
 578→ */
 579→const PLUGIN_SEARCH_HARD_TOPK = 50;
 580→
 581→/** Default `top_k` the LLM sees if it doesn't specify one. Matches plugin default. */
 582→const DEFAULT_SEARCH_TOPK = 10;
 583→
 584→/**
 585→ * Default resolver: call kernel /v3/meta/asset/list-accessible each time.
 586→ *
 587→ * Failure: kernel call throws → propagate; skill-bridge fail-closes with
 588→ * empty items so LLM never sees an unfiltered team search.
 589→ */
 590→function defaultVisibleSkillIdsResolver(
 591→  config: ProxyConfig,
 592→): VisibleSkillIdsResolver {
 593→  return async ({ user_id, team_id, user_key, space_id }) => {
 594→    // Use the real space_id from the request (kernel routes tenants by
 595→    // x-tdai-service-id header) — fall back to config only for legacy sessions.
 596→    const serviceId = space_id || config.coreSkill.serviceId;
 597→    const client = getMetadataClient(config.coreSkill, serviceId, user_key);
 598→    const assets = await client.listAccessibleAssets({
 599→      user_id,
 600→      team_id,
 601→      asset_type: "skill",
 602→      action: "read",
 603→      // The model's path (2026-09-08): admitted assets this user may read —
 604→      // team-shared ones and the caller's own, private included. Other
 605→      // people's private and ACL-restricted skills stay out because the
 606→      // kernel's permission check keeps them out, not because of a
 607→      // visibility filter here; candidates and rejected skills stay out
 608→      // whoever owns them.
 609→      purpose: "use",
 610→    });
 611→    // For skill assets, asset_id === skill_id by kernel convention.
 612→    return {
 613→      ids: assets.map((a) => a.asset_id),
 614→      assets: assets.map((a) => ({ asset_id: a.asset_id, name: a.name, owner_user_id: a.owner_user_id })),
 615→    };
 616→  };
 617→}
 618→
 619→/**
 620→ * Build a Hono-compatible handler. Hono passes its `Context`; we use `c.req.raw`
 621→ * to get the underlying Request, then issue an outbound fetch and adapt the
 622→ * response back to a `Response`.
 623→ */
 624→export function createSkillBridgeHandler(
 625→  config: ProxyConfig,
 626→  deps: SkillBridgeDeps = {},
 627→): (c: Context) => Promise<Response> {
 628→  const fetcher = deps.fetcher ?? globalThis.fetch.bind(globalThis);
 629→
 630→  return async (c: Context): Promise<Response> => {
 631→    const t0 = (deps.now ?? Date.now)();
 632→
 633→    const path = new URL(c.req.url).pathname;
 634→    const sub = extractSubpath(path);
 635→    // 前置校验早退埋点: 每个 return 前都发一条 reject_reason 非空的 bridge_call。
 636→    // sessionKey 此刻可能还没派生, 允许传 "" (helper 兜底 agentSource='unknown')。
 637→    if (!sub) {
 638→      emitBridgeRejectTelemetry({
 639→        sessionKey: "", bridgeSource: "skill-bridge",
 640→        rejectReason: "unknown_path", httpStatus: 404,
 641→      });
 642→      return envelope(40401, `${TAG} unknown path ${path}`, 404);
 643→    }
 644→    if (!ALLOWED_SUBPATHS.has(sub)) {
 645→      emitBridgeRejectTelemetry({
 646→        sessionKey: "", bridgeSource: "skill-bridge",
 647→        rejectReason: "subpath_forbidden", httpStatus: 403,
 648→        executedEndpoint: sub,
 649→      });
 650→      return envelope(40301, `${TAG} subpath '${sub}' not allowed via bridge`, 403);
 651→    }
 652→    if (c.req.method !== "POST") {
 653→      emitBridgeRejectTelemetry({
 654→        sessionKey: "", bridgeSource: "skill-bridge",
 655→        rejectReason: "method_not_allowed", httpStatus: 405,
 656→        executedEndpoint: sub,
 657→      });
 658→      return envelope(40501, `${TAG} method ${c.req.method} not allowed`, 405);
 659→    }
 660→
 661→    const ct = c.req.header("content-type") ?? "";
 662→    if (!ct.toLowerCase().includes("application/json")) {
 663→      emitBridgeRejectTelemetry({
 664→        sessionKey: "", bridgeSource: "skill-bridge",
 665→        rejectReason: "content_type_invalid", httpStatus: 415,
 666→        executedEndpoint: sub,
 667→      });
 668→      return envelope(41501, `${TAG} content-type must be application/json`, 415);
 669→    }
 670→
 671→    // Session must be initialized — IdFields come from there.
 672→    // curl 模板只带 (x-conversation-id, x-tdai-service-id) 两个 header;
 673→    // L1 miss 时用它俩去 nottl/<spaceId>/<sessionId>/binding.json 反查。
 674→    const sessionKey = deriveSessionId(c);
 675→    if (!sessionKey) {
 676→      emitBridgeRejectTelemetry({
 677→        sessionKey: "", bridgeSource: "skill-bridge",
 678→        rejectReason: "missing_conversation_id", httpStatus: 401,
 679→        executedEndpoint: sub,
 680→      });
 681→      return envelope(40101, `${TAG} missing x-conversation-id (or x-session-id / x-chat-id / x-thread-id) header`, 401);
 682→    }
 683→    const spaceId = c.req.header("x-tdai-service-id")
 684→      ?? config.tdai?.serviceId
 685→      ?? config.coreSkill?.serviceId
 686→      ?? "";
 687→
 688→    // Backing storage for extract trigger + version pin.
 689→    // When storage.enabled + mode!=off → ProxyStorage (Kv* repos).
 690→    // Otherwise → Redis (or null when disabled).
 691→    const backing = resolveBacking(config);
 692→    const pinRepoInline = backing.pinRepo;
 693→    const bindingRepoInline = backing.bindingRepo;
 694→
 695→    let ids = loadSessionIdsL1(sessionKey);
 696→    if (!ids && bindingRepoInline && spaceId) {
 697→      console.log(`${TAG} session=${sessionKey} L1 miss → L2 binding lookup (space=${spaceId})`);
 698→      ids = await loadSessionIdsL2(bindingRepoInline, spaceId, sessionKey);
 699→    }
 700→    if (!ids) {
 701→      emitBridgeRejectTelemetry({
 702→        sessionKey, bridgeSource: "skill-bridge",
 703→        rejectReason: "session_not_initialized", httpStatus: 401,
 704→        executedEndpoint: sub, spaceId,
 705→      });
 706→      return envelope(40101, `${TAG} session not initialized; cannot derive identity`, 401);
 707→    }
 708→    // backing.redis 之前给老链路 SkillExtractTrigger 用, 老链路已删,
 709→    // 本函数体内不再直接使用 redis; backing 结构上保留是因为 pinRepo
 710→    // 走 redis 的分支还需要它。
 711→
 712→    // 消融实验：allowLlmWrite=false 时拒绝写操作
 713→    const allowLlmWrite = config.skillRuntime?.allowLlmWrite ?? false;
 714→    if (!allowLlmWrite && WRITE_SUBPATHS.has(sub)) {
 715→      emitBridgeRejectTelemetry({
 716→        sessionKey, bridgeSource: "skill-bridge",
 717→        rejectReason: "write_ops_disabled", httpStatus: 403,
 718→        executedEndpoint: sub,
 719→        spaceId: ids.space_id, userId: ids.user_id, teamId: ids.team_id,
 720→        agentId: ids.agent_id, agentSource: ids.agent_source,
 721→      });
 722→      return envelope(40302, `${TAG} LLM write access to skill is disabled (skillRuntime.allowLlmWrite=false)`, 403);
 723→    }
 724→
 725→    // Parse body. Empty body → {}. Malformed → 400.
 726→    let inboundBody: Record<string, unknown> = {};
 727→    try {
 728→      const raw = await c.req.text();
 729→      if (raw && raw.trim()) {
 730→        const parsed = JSON.parse(raw);
 731→        if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
 732→          inboundBody = parsed as Record<string, unknown>;
 733→        } else {
 734→          emitBridgeRejectTelemetry({
 735→            sessionKey, bridgeSource: "skill-bridge",
 736→            rejectReason: "body_not_object", httpStatus: 400,
 737→            executedEndpoint: sub, requestBody: raw.slice(0, 512),
 738→            spaceId: ids.space_id, userId: ids.user_id, teamId: ids.team_id,
 739→            agentId: ids.agent_id, agentSource: ids.agent_source,
 740→          });
 741→          return envelope(40001, `${TAG} body must be a JSON object`, 400);
 742→        }
 743→      }
 744→    } catch (err) {
 745→      emitBridgeRejectTelemetry({
 746→        sessionKey, bridgeSource: "skill-bridge",
 747→        rejectReason: "invalid_json_body", httpStatus: 400,
 748→        executedEndpoint: sub,
 749→        spaceId: ids.space_id, userId: ids.user_id, teamId: ids.team_id,
 750→        agentId: ids.agent_id, agentSource: ids.agent_source,
 751→      });
 752→      return envelope(40001, `${TAG} invalid JSON body: ${(err as Error).message}`, 400);
 753→    }
 754→
 755→    // ── files/download: read from core, decode, return raw bytes ──────
 756→    // LLM uses `curl -o <local_path>` to save directly; no JSON parsing needed.
 757→    if (sub === "files/download") {
 758→      const outbound = {
 759→        ...inboundBody,
 760→        user_id: ids.user_id,
 761→        team_id: ids.team_id,
 762→        agent_id: ids.agent_id,
 763→      };
 764→      const upstreamUrl = `${config.coreSkill.endpoint.replace(/\/$/, "")}/v3/skill/files/read`;
 765→      const headers: Record<string, string> = {
 766→        "Authorization": `Bearer [REDACTED]
 767→        // Prefer session-derived tenant; fall back to config for legacy sessions.
 768→        "x-tdai-service-id": ids.space_id || config.coreSkill.serviceId,
 769→        "Content-Type": "application/json",
 770→      };
 771→      const dlOutboundBody = JSON.stringify(outbound);
 772→      const dlCallStart = (deps.now ?? Date.now)();
 773→      let coreResp: Response;
 774→      try {
 775→        coreResp = await fetcher(upstreamUrl, {
 776→          method: "POST",
 777→          headers,
 778→          body: dlOutboundBody,
 779→          signal: AbortSignal.timeout(Math.max(5000, config.coreSkill.timeoutMs * 4)),
 780→        });
 781→      } catch (err) {
 782→        console.warn(`${TAG} files/download upstream fetch failed: ${(err as Error).message}`);
 783→        // 埋点补齐: 与主路径 :822 对称, upstream 未响应也算一次调用。
 784→        // 之前这个 catch 分支静默 return, 导致 curl 视角"打了 N 次" CH 少一条。
 785→        const dlEmitKey = ids.composite_key ?? sessionKey;
 786→        emitBridgeToolCallTelemetry({
 787→          sessionKey: dlEmitKey,
 788→          spaceId: ids.space_id,
 789→          userId: ids.user_id,
 790→          teamId: ids.team_id,
 791→          agentId: ids.agent_id,
 792→          agentSource: ids.agent_source || agentSourceFromSessionKey(dlEmitKey),
 793→          bridgeSource: "skill-bridge",
 794→          executedEndpoint: "files/download",
 795→          requestBody: dlOutboundBody.slice(0, 512),
 796→          upstreamStatus: 0,
 797→          elapsedMs: (deps.now ?? Date.now)() - dlCallStart,
 798→        });
 799→        return envelope(50301, `${TAG} upstream unavailable: ${(err as Error).message}`, 502);
 800→      }
 801→      const coreText = await coreResp.text().catch(() => "");
 802→      const elapsed = (deps.now ?? Date.now)() - t0;
 803→      console.log(`${TAG} sub=files/download status=${coreResp.status} elapsed=${elapsed}ms`);
 804→
 805→      // Core error → pass through as JSON envelope
 806→      if (coreResp.status < 200 || coreResp.status >= 300) {
 807→        return new Response(coreText, {
 808→          status: coreResp.status,
 809→          headers: { "content-type": coreResp.headers.get("content-type") ?? "application/json" },
 810→        });
 811→      }
 812→
 813→      // Parse envelope, extract file content
 814→      let parsed: { code?: number; data?: { content?: string; encoding?: string; mime_type?: string; size_bytes?: number } };
 815→      try {
 816→        parsed = JSON.parse(coreText);
 817→      } catch {
 818→        return envelope(50001, `${TAG} files/download: failed to parse core response`, 502);
 819→      }
 820→      if (parsed.code !== 0 || !parsed.data?.content) {
 821→        return new Response(coreText, {
 822→          status: coreResp.status,
 823→          headers: { "content-type": "application/json" },
 824→        });
 825→      }
 826→
 827→      const { content, encoding, mime_type } = parsed.data;
 828→      const rawBytes = encoding === "base64"
 829→        ? Buffer.from(content, "base64")
 830→        : Buffer.from(content, "utf-8");
 831→
 832→      return new Response(rawBytes, {
 833→        status: 200,
 834→        headers: {
 835→          "content-type": mime_type ?? "application/octet-stream",
 836→          "content-length": String(rawBytes.length),
 837→        },
 838→      });
 839→    }
 840→
 841→    // Stamp identity. team_id / agent_id / user_id are all required by
 842→    // the v3 strict-isolation middleware (collectV3Missing in v2-router.ts).
 843→    //
 844→    // user_id was historically skipped for read paths to avoid filtering
 845→    // team-shared skills, but the v2 gateway now requires it for all /v3/*
 846→    // paths.  The core layer handles this safely: when team_id is present,
 847→    // core strips user_id before passing to store (skill-core.ts:365,384).
 848→    //
 849→    // For "search" subpath, we additionally stamp scope="team" so the
 850→    // handler can skip agent_id owner-filtering and do a team-wide search.
 851→    const isTeamWideSearch = sub === "search";
 852→    /**
 853→     * When we enter team-wide search, the whitelist we compute here also drives
 854→     * the response-side filter (see below, after upstream response arrives). Kept
 855→     * in the outer scope so the response handler can see it without a second
 856→     * meta call. `originalTopK` is what the LLM asked for; we overfetch to
 857→     * PLUGIN_SEARCH_HARD_TOPK from plugin to survive whitelist attrition, then
 858→     * slice back to originalTopK before returning.
 859→     */
 860→    let searchVisibleIds: Set<string> | null = null;
 861→    let searchOriginalTopK = 0;
 862→    let outbound: Record<string, unknown>;
 863→    /**
 864→     * upstream 路径若与 `/v3/skill/${sub}` 不一致(如 extract → force-archive)
 865→     * 由分支写这个变量;默认沿用 sub。
 866→     */
 867→    let upstreamSubpathOverride: string | null = null;
 868→    if (sub === "extract") {
 869→      // agent 侧 tool 叫 skill_extract, 语义"立即归档当前对话触发一次 skill 抽取"。
 870→      // 转发到 core `/v3/skill/conversation/force-archive` —— 该接口不吃 messages,
 871→      // 从 conversation buffer(proxy 主对话链路每轮推的 /v3/skill/conversation/add)
 872→      // 拿累积的完整对话。见 core skill-schemas.ts forceArchiveRequestSchema。
 873→      //
 874→      // outbound 只需 (space_id, user_id, team_id, agent_id, session_id) + 可选 reason;
 875→      // agent 传的 messages / task_id 一律不透传(agent 视角无关,session 内隐含)。
 876→      upstreamSubpathOverride = "conversation/force-archive";
 877→      const reason = typeof inboundBody.reason === "string" && inboundBody.reason.trim()
 878→        ? inboundBody.reason.trim().slice(0, 2000)
 879→        : undefined;
 880→      outbound = {
 881→        space_id: ids.space_id || config.coreSkill.serviceId,
 882→        user_id: ids.user_id,
 883→        team_id: ids.team_id,
 884→        agent_id: ids.agent_id,
 885→        session_id: (() => {
 886→          const composite = ids.composite_key ?? sessionKey;
 887→          const colonIdx = composite.indexOf(":");
 888→          return colonIdx > 0 ? composite.slice(colonIdx + 1) : composite;
 889→        })(),
 890→        ...(reason ? { reason } : {}),
 891→      };
 892→    } else {
 893→      // v3 strict-isolation: ALL /v3 paths need team_id + agent_id + user_id.
 894→      // Core layer strips user_id when team_id is present (team-shared semantics).
 895→      outbound = {
 896→        ...inboundBody,
 897→        team_id: ids.team_id,
 898→        agent_id: ids.agent_id,
 899→        user_id: ids.user_id,
 900→      };
 901→      // For "search" subpath: stamp scope="team" so the handler skips
 902→      // agent_id owner-filtering → team-wide search.
 903→      if (isTeamWideSearch) {
 904→        // Enforce visibility whitelist via **control-plane / data-plane composition**.
 905→        //
 906→        // Layering (see design discussion 2026-07-07):
 907→        //   - Plugin (/v3/skill/*) is the data plane — pure business logic
 908→        //     (CRUD + FTS). It does NOT know about ACL/visibility. Do not
 909→        //     push authorization concerns into it.
 910→        //   - Meta (/v3/meta/*) is the control plane — owns visibility × ACL.
 911→        //     Frontend team-assets tab already composes on it
 912→        //     (SkillsPanel.tsx: list-accessible + visibility='team').
 913→        //   - Proxy composes: consult meta for a visibility whitelist, call
 914→        //     plugin unchanged, filter the response.
 915→        //
 916→        // Contract:
 917→        //   - Missing user_key → programming bug (session-init should have
 918→        //     stored it). Return 500 rather than silently opening up.
 919→        //   - Resolver throws → fail-closed: return {items: []}. Never widen
 920→        //     to an unfiltered search on infra failure.
 921→        //   - Empty whitelist → short-circuit: return {items: []} without
 922→        //     hitting core (user has 0 visible team skills).
 923→        //   - Non-empty whitelist → overfetch top_k=PLUGIN_SEARCH_HARD_TOPK,
 924→        //     filter response items by whitelist, slice back to caller's top_k.
 925→        if (!ids.user_key) {
 926→          console.error(`${TAG} team search: session lacks user_key — session-init should have stored it (sessionKey=${sessionKey})`);
 927→          return envelope(50001, `${TAG} team search misconfigured: session has no user_key`, 500);
 928→        }
 929→
 930→        // Whitelist = A ∪ B（见 docs/design/2026-08-10-skill-search-scope-fix.md §4）：
 931→        //   A = meta list-accessible(visibility='team') — team-shared skill
 932→        //   B = core /v3/skill/list(agent 自有全量)   — 含 private
 933→        //
 934→        // 原来有 C = listing "本会话已注入" 做减法，但 C 是实时 listing 结果，
 935→        // 会话内新建的 skill 会出现在 C 中被减掉 → 搜不到 (Issue #1006)。
 936→        // 去掉 C 减法：代价是已注入 skill 可能重复出现在搜索结果中（无害），
 937→        // 但不会有"永远搜不到"的盲区。
 938→        //
 939→        // 失败降级策略：
 940→        //   A 失败 → fail-closed 返回空（安全兜底：绝不让 LLM 看到未过滤结果）
 941→        //   B 失败 → 当空集，退化为纯 A（约等于修复前行为）
 942→        const coreClient = deps.coreClient ?? getCoreSkillClient(config.coreSkill);
 943→        const resolver = deps.resolveVisibleSkillIds
 944→          ?? defaultVisibleSkillIdsResolver(config);
 945→
 946→        const promiseA = resolver({
 947→          user_id: ids.user_id,
 948→          team_id: ids.team_id,
 949→          user_key: ids.user_key,
 950→          space_id: ids.space_id,
 951→        }).then(r => ({ ok: true as const, ids: r.ids }))
 952→          .catch(err => ({ ok: false as const, err: err as Error }));
 953→
 954→        // B limit=1000 是 core listRequestSchema 上限（paginationSchema.limit.max(1000)）。
 955→        // 单 agent 自有 skill 到不了 1000 量级，一次拿完不分页。
 956→        const promiseB = coreClient.listSkills(
 957→          {
 958→            team_id: ids.team_id,
 959→            agent_id: ids.agent_id,
 960→            pagination: { limit: 1000 },
 961→          },
 962→          { serviceId: ids.space_id },
 963→        ).then(r => r.items.map(s => s.skill_id))
 964→          .catch(err => {
 965→            console.warn(`${TAG} team search B (list) failed, treating as empty: ${(err as Error).message}`);
 966→            return [] as string[];
 967→          });
 968→
 969→        const [aResult, bIds] = await Promise.all([promiseA, promiseB]);
 970→
 971→        if (!aResult.ok) {
 972→          // Fail-closed: A 挂掉不能降级到不过滤搜索。
 973→          console.warn(`${TAG} team search whitelist resolver (A) failed, fail-closed: ${aResult.err.message}`);
 974→          return new Response(
 975→            JSON.stringify({ code: 0, message: "ok", request_id: `bridge-${(deps.now ?? Date.now)()}`, data: { items: [] } }),
 976→            { status: 200, headers: { "content-type": "application/json" } },
 977→          );
 978→        }
 979→
 980→        const whitelist: string[] = Array.from(new Set<string>([...aResult.ids, ...bIds]));
 981→        console.log(
 982→          `${TAG} team search whitelist A=${aResult.ids.length} B=${bIds.length}`
 983→            + ` merged=${whitelist.length} user=${ids.user_id} team=${ids.team_id}`,
 984→        );
 985→
 986→        if (whitelist.length === 0) {
 987→          // Short-circuit: no visible skill IDs → 0 matches guaranteed. Skip upstream.
 988→          return new Response(
 989→            JSON.stringify({ code: 0, message: "ok", request_id: `bridge-${(deps.now ?? Date.now)()}`, data: { items: [] } }),
 990→            { status: 200, headers: { "content-type": "application/json" } },
 991→          );
 992→        }
 993→
 994→        // Stash the whitelist Set + fixed slice size so the response handler
 995→        // can filter/slice without re-consulting meta.
 996→        //
 997→        // 2026-08-10: Hard-whitelist inbound. LLM only supplies `query` —
 998→        // top_k / mode / scope / any other field is dropped. Rationale:
 999→        // less LLM-side decision surface, more consistent behavior across
1000→        // sessions. If results feel thin, the fix is to refine the query,
1001→        // not to raise top_k. See skill-tools-injector.ts (body: {"query": ...}).
1002→        searchVisibleIds = new Set(whitelist);
1003→        searchOriginalTopK = DEFAULT_SEARCH_TOPK;
1004→
1005→        const query = typeof inboundBody.query === "string" ? inboundBody.query : "";
1006→        outbound = {
1007→          query,
1008→          team_id: ids.team_id,
1009→          agent_id: ids.agent_id,
1010→          user_id: ids.user_id,
1011→          scope: "team",
1012→          // Overfetch to plugin's hard cap so response-side filtering has room.
1013→          // Plugin remains unaware of proxy's ACL concerns — it just sees a
1014→          // large-but-legal top_k. See PLUGIN_SEARCH_HARD_TOPK doc for why this
1015→          // is safe.
1016→          top_k: PLUGIN_SEARCH_HARD_TOPK,
1017→        };
1018→      }
1019→
1020→      // ── Read visibility: the same whitelist search uses, applied to reads ──
1021→      if (READ_VISIBILITY_OPS.has(sub)) {
1022→        if (!ids.user_key) {
1023→          console.error(`${TAG} read visibility: session lacks user_key — session-init should have stored it (sessionKey=${sessionKey})`);
1024→          return envelope(50001, `${TAG} read misconfigured: session has no user_key`, 500);
1025→        }
1026→        const wl = await computeReadWhitelist({
1027→          ids,
1028→          resolver: deps.resolveVisibleSkillIds ?? defaultVisibleSkillIdsResolver(config),
1029→          coreClient: deps.coreClient ?? getCoreSkillClient(config.coreSkill),
1030→        });
1031→        if (!wl.ok) {
1032→          // Fail-closed, as search does: an infra failure must not widen a read.
1033→          console.warn(`${TAG} read whitelist resolver (A) failed, fail-closed: ${wl.err.message}`);
1034→          emitBridgeRejectTelemetry({
1035→            sessionKey, bridgeSource: "skill-bridge",
1036→            rejectReason: "visibility_unavailable", httpStatus: 403,
1037→            executedEndpoint: sub,
1038→            spaceId: ids.space_id, userId: ids.user_id, teamId: ids.team_id,
1039→            agentId: ids.agent_id, agentSource: ids.agent_source,
1040→          });
1041→          return envelope(40301, `${TAG} visibility could not be resolved; read refused`, 403);
1042→        }
1043→
1044→        const decision = decideReadVisibility({
1045→          sub, inboundBody, whitelist: wl.whitelist, teamSkills: wl.teamSkills, callerAgentId: ids.agent_id,
1046→        });
1047→        if (decision.kind === "reject") {
1048→          emitBridgeRejectTelemetry({
1049→            sessionKey, bridgeSource: "skill-bridge",
1050→            rejectReason: decision.reason, httpStatus: 403,
1051→            executedEndpoint: sub,
1052→            spaceId: ids.space_id, userId: ids.user_id, teamId: ids.team_id,
1053→            agentId: ids.agent_id, agentSource: ids.agent_source,
1054→          });
1055→          return envelope(40301, `${TAG} ${decision.message}`, 403);
1056→        }
1057→        if (decision.kind === "rewrite") {
1058→          // A name that resolved to a visible skill — possibly another agent's —
1059→          // is read by id, which core scopes by team. The include_* flags the
1060→          // caller sent are preserved; the name itself is no longer needed.
1061→          upstreamSubpathOverride = "get";
1062→          outbound = {
1063→            skill_id: decision.skillId,
1064→            ...(inboundBody.include_content !== undefined ? { include_content: inboundBody.include_content } : {}),
1065→            ...(inboundBody.include_manifest !== undefined ? { include_manifest: inboundBody.include_manifest } : {}),
1066→            team_id: ids.team_id,
1067→            agent_id: ids.agent_id,
1068→            user_id: ids.user_id,
1069→          };
1070→          console.log(`${TAG} get-by-name resolved to ${decision.skillId} via visibility whitelist (agent=${ids.agent_id})`);
1071→        }
1072→      }
1073→
1074→      // ── Version pinning: inject pinned version for read/write ops ──
1075→      // Read (get/files_read): inject `version` → plugin returns pinned version's content
1076→      // Write (update/patch/files_write/files_remove): inject `expected_version` → optimistic lock
1077→      // First-access is not pinned yet → falls through to head; lazy-pin captures the version afterwards.
1078→      if (pinRepoInline && (READ_VERSION_OPS.has(sub) || WRITE_LOCK_OPS.has(sub))) {
1079→        const skillId = typeof inboundBody.skill_id === "string" ? inboundBody.skill_id : undefined;
1080→        if (skillId) {
1081→          const pinRepo = pinRepoInline;
1082→          const pinned = await pinRepo.getVersion(ids.space_id ?? "", ids.user_id, ids.agent_source, sessionKey, skillId);
1083→          if (pinned !== null && pinned !== undefined) {
1084→            if (READ_VERSION_OPS.has(sub)) {
1085→              outbound.version = pinned;
1086→            } else {
1087→              outbound.expected_version = pinned;
1088→            }
1089→          }
1090→          // else: first access → walk head, response side will lazy-pin.
1091→        }
1092→      }
1093→    }
1094→
1095→    const upstreamSub = upstreamSubpathOverride ?? sub;
1096→    const upstreamUrl = `${config.coreSkill.endpoint.replace(/\/$/, "")}/v3/skill/${upstreamSub}`;
1097→    const headers: Record<string, string> = {
1098→      "Authorization": `Bearer [REDACTED]
1099→      // Prefer session-derived tenant; fall back to config for legacy sessions.
1100→      "x-tdai-service-id": ids.space_id || config.coreSkill.serviceId,
1101→      "Content-Type": "application/json",
1102→    };
1103→
1104→    const outboundBody = JSON.stringify(outbound);
1105→    const callStart = (deps.now ?? Date.now)();
1106→    let resp: Response;
1107→    try {
1108→      resp = await fetcher(upstreamUrl, {
1109→        method: "POST",
1110→        headers,
1111→        body: outboundBody,
1112→        signal: AbortSignal.timeout(Math.max(5000, config.coreSkill.timeoutMs * 4)),
1113→      });
1114→    } catch (err) {
1115→      console.warn(
1116→        `${TAG} upstream fetch failed sub=${sub} err=${(err as Error).message}`,
1117→      );
1118→      // 埋点：upstream 未响应也算一次调用（方案 §5.1"每次都要记录"）
1119→      // 用 ids.composite_key 保证 session_key 与 session_init_logs 对齐。
1120→      const emitKey = ids.composite_key ?? sessionKey;
1121→      emitBridgeToolCallTelemetry({
1122→        sessionKey: emitKey,
1123→        spaceId: ids.space_id,
1124→        userId: ids.user_id,
1125→        teamId: ids.team_id,
1126→        agentId: ids.agent_id,
1127→        agentSource: ids.agent_source || agentSourceFromSessionKey(emitKey),
1128→        bridgeSource: "skill-bridge",
1129→        executedEndpoint: sub,
1130→        requestBody: outboundBody.slice(0, 512),
1131→        upstreamStatus: 0,
1132→        elapsedMs: (deps.now ?? Date.now)() - callStart,
1133→      });
1134→      return envelope(50301, `${TAG} upstream unavailable: ${(err as Error).message}`, 502);
1135→    }
1136→
1137→    const respText = await resp.text().catch(() => "");
1138→    const elapsed = (deps.now ?? Date.now)() - t0;
1139→    console.log(
1140→      `${TAG} sub=${sub} status=${resp.status} elapsed=${elapsed}ms`,
1141→    );
1142→
1143→    // 埋点：upstream 已响应（含 4xx/5xx），记录实际状态与耗时
1144→    const emitKey = ids.composite_key ?? sessionKey;
1145→    emitBridgeToolCallTelemetry({
1146→      sessionKey: emitKey,
1147→      spaceId: ids.space_id,
1148→      userId: ids.user_id,
1149→      teamId: ids.team_id,
1150→      agentId: ids.agent_id,
1151→      agentSource: ids.agent_source || agentSourceFromSessionKey(emitKey),
1152→      bridgeSource: "skill-bridge",
1153→      executedEndpoint: sub,
1154→      requestBody: outboundBody.slice(0, 512),
1155→      upstreamStatus: resp.status,
1156→      elapsedMs: (deps.now ?? Date.now)() - callStart,
1157→    });
1158→
1159→    // 曾经这里会在写操作 / extract 成功时清零 proxy 侧 buffer 计数器,
1160→    // 避免重复触发自动 extract。老链路 (SkillExtractTrigger + KvExtractStore)
1161→    // 已删除, 该逻辑不再需要。
1162→
1163→    // ── Team-wide search: response-side visibility filter ──
1164→    // We composed with meta above and stashed the visible skill_id set
1165→    // (searchVisibleIds) + the caller's original top_k (searchOriginalTopK).
1166→    // Filter data.items by the whitelist and slice back so plugin's overfetch
1167→    // stays invisible to the caller. This runs BEFORE lazy-pin so pinning
1168→    // only records versions the caller actually gets to see.
1169→    let finalRespText = respText;
1170→    if (
1171→      isTeamWideSearch
1172→      && searchVisibleIds
1173→      && resp.status >= 200
1174→      && resp.status < 300
1175→    ) {
1176→      finalRespText = filterTeamSearchResponse(respText, searchVisibleIds, searchOriginalTopK);
1177→    }
1178→
1179→    // ── Lazy-pin: extract version from response and record in pin repo ──
1180→    // Only on 2xx success; failures don't advance the pin. Use the FILTERED
1181→    // response so we don't pin versions of skills the caller can't see.
1182→    if (pinRepoInline && resp.status >= 200 && resp.status < 300) {
1183→      await tryLazyPin(sub, finalRespText, ids.space_id ?? "", ids.user_id, ids.agent_source, sessionKey, pinRepoInline).catch(() => {});
1184→    }
1185→
1186→    return new Response(finalRespText, {
1187→      status: resp.status,
1188→      headers: {
1189→        "content-type": resp.headers.get("content-type") ?? "application/json",
1190→      },
1191→    });
1192→  };
