 1→/**
 2→ * Independent reachability probe — the "independent validator" the outcome
 3→ * judge needs before it may call an asset wrong.
 4→ *
 5→ * A model's call timing out at an address proves the model followed the
 6→ * asset that gave it the address. It does not prove the address is wrong: the
 7→ * right address can time out once. So the harness itself opens a TCP
 8→ * connection to every host:port the run attempted and records the result.
 9→ * The judge treats a failed call as `corrected(wrong)` only when this probe
10→ * also failed to reach the address; when the probe reaches it, the model's
11→ * failure was environmental and the outcome is `needs_review`.
12→ *
13→ * The record says when it was taken and by whom (`source`). A probe taken at
14→ * run time can speak to the state at run time; one taken afterwards can only
15→ * say the address is persistently unreachable or reachable now, and the judge
16→ * carries that wording through.
17→ *
18→ * Usage:
19→ *   node probe-reachability.mjs --verdict=verdict.json --out=reachability.json [--source="harness probe at run time"] [--timeout-ms=5000]
20→ *   node probe-reachability.mjs --targets=10.244.7.19:8096,127.0.0.1:47318 --out=reachability.json
21→ */
22→
23→import { readFileSync, writeFileSync } from "node:fs";
24→import { connect } from "node:net";
25→
26→/** TCP-connect once; resolves {ok, why, elapsed_ms}. Never rejects. */
27→export function probe(host, port, { timeoutMs = 5000 } = {}) {
28→  return new Promise((resolve) => {
29→    const started = Date.now();
30→    let done = false;
31→    const finish = (ok, why) => {
32→      if (done) return;
33→      done = true;
34→      try { socket.destroy(); } catch { /* already closed */ }
35→      resolve({ ok, why, elapsed_ms: Date.now() - started });
36→    };
37→    const socket = connect({ host, port: Number(port) });
38→    socket.setTimeout(timeoutMs);
39→    socket.once("connect", () => finish(true, "tcp connect ok"));
40→    socket.once("timeout", () => finish(false, "timed out"));
41→    socket.once("error", (err) => finish(false, err?.code === "ECONNREFUSED" ? "could not connect" : `error ${err?.code ?? err?.message ?? "unknown"}`));
42→  });
43→}
44→
45→/** Distinct host:port targets from a verdict's attempts. */
46→export function targetsOf(verdictDoc) {
47→  const seen = new Set();
48→  for (const a of verdictDoc?.attempts ?? []) {
49→    if (a?.host && a?.port) seen.add(`${a.host}:${a.port}`);
50→  }
51→  return [...seen];
52→}
53→
54→export async function probeAll(targets, { timeoutMs = 5000, source = "harness probe" } = {}) {
55→  const checkedAt = new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
